/bin/bash -lc "cat > /tmp/user-profile-check.mjs <<'EOF'
import http from 'node:http'
import { spawn } from 'node:child_process'
import assert from 'node:assert/strict'

const requests = []
const api = http.createServer((req, res) => {
  requests.push({ url: req.url, cookie: req.headers.cookie, authorization: req.headers.authorization })
  if (req.headers.cookie === 'scenario=error') {
    res.writeHead(500).end()
  } else if (req.headers.cookie === 'scenario=invalid') {
    res.writeHead(200, { 'content-type': 'application/json' }).end('{\"name\":\"Invalid\"}')
  } else {
    const isSecond = req.headers.cookie === 'session=second'
    res.writeHead(200, { 'content-type': 'application/json' }).end(JSON.stringify({
      name: isSecond ? 'Second User' : 'First User',
      email: isSecond ? 'second@example.com' : 'first@example.com',
    }))
  }
})
await new Promise(resolve => api.listen(0, '127.0.0.1', resolve))
const appPort = 34571
const app = spawn(process.execPath, ['node_modules/next/dist/bin/next', 'start', '-p', String(appPort)], {
  cwd: '/workspace',
  env: { ...process.env, APP_ORIGIN: "'`http://127.0.0.1:${api.address().port}` },
  stdio: ['"'ignore', 'pipe', 'pipe'],
})
let output = ''
app.stdout.on('data', chunk => { output += chunk })
app.stderr.on('data', chunk => { output += chunk })
try {
  for (let attempts = 0; "'!output.includes('"'Ready'); attempts++) {
    if (attempts >= 100 || app.exitCode "'!== null) throw new Error(`App failed to start: ${output}`)
    await new Promise(resolve => setTimeout(resolve, 100))
  }
  const getPage = async cookie => (await fetch(`http://127.0.0.1:${appPort}`, {
    headers: { cookie, authorization: '"'Bearer test-token', host: 'attacker.invalid' },
  })).text()
  const first = await getPage('session=first')
  assert.match(first, /First User/)
  assert.match(first, /first@example\\.com/)
  const second = await getPage('session=second')
  assert.match(second, /Second User/)
  assert.match(second, /second@example\\.com/)
  assert.doesNotMatch(second, /First User/)
  assert.match(await getPage('scenario=error'), /Unable to load user profile/)
  assert.match(await getPage('scenario=invalid'), /Unable to load user profile/)
  assert.deepEqual(requests.map(request => request.url), Array(4).fill('/api/users/profile'))
  assert.equal(requests[0].cookie, 'session=first')
  assert.equal(requests[0].authorization, 'Bearer test-token')
  console.log('Profile integration checks passed: rendering, per-user data, credentials, failures, and trusted origin.')
} finally {
  app.kill()
  api.close()
}
EOF
node /tmp/user-profile-check.mjs"

